select * from customer limit 10 

--Q1. What is the total revenue generated by male vs. female customers?
select gender , sum(purchase_amount) as revenue from customer group by gender  

--Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount >= (
      SELECT AVG(purchase_amount)
      FROM customer
  )

--Q3. Which are the top 5 products with the highest average review rating?
SELECT
    item_purchased,
    ROUND(AVG(review_rating::numeric),2) AS average_product_rating
FROM customer
GROUP BY item_purchased
ORDER BY average_product_rating DESC
LIMIT 5;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
select ROUND(avg(purchase_amount::numeric),2) , shipping_type 
from customer
where shipping_type in ('Express' ,'Standard') group by shipping_type;

--Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.

select subscription_status , ROUND(avg(purchase_amount::numeric),2) as average_spend, sum(purchase_amount) as total_revenue ,sum(customer_id) as total_customer
from customer 
group by subscription_status;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT
    item_purchased,
    ROUND(
        100.0 * SUM(
            CASE
                WHEN discount_applied = 'Yes' THEN 1
                ELSE 0
            END
        ) / COUNT(*),
        2
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

--Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.

-- Q7. Segment customers into New, Returning, and Loyal
-- and show the count of each segment.

WITH customer_type AS (
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer
)
SELECT
    customer_segment,
    COUNT(DISTINCT customer_id) AS customer_count
FROM customer_type
GROUP BY customer_segment
ORDER BY customer_count DESC;

--Q8. What are the top 3 most purchased products within each category?

WITH product_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(*) AS total_purchases
    FROM customer
    GROUP BY category, item_purchased
),
ranked_products AS (
    SELECT
        category,
        item_purchased,
        total_purchases,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY total_purchases DESC
        ) AS product_rank
    FROM product_counts
)
SELECT
    category,
    item_purchased,
    total_purchases
FROM ranked_products
WHERE product_rank <= 3
ORDER BY category, product_rank;

--Q10. What is the revenue contribution of each age group?
select 
 case 
   when previous_purchases >5 then 'repeat Buyers'
   else 'Others Customers'
  end as customer_type,
  subscription_status,
  COUNT(DISTINCT customer_id) AS total_customers
from customer
group by
 customer_type,
 subscription_status
order by 
  customer_type,
  subscription_status;

 
  




 